const STORAGE_KEY='terrarium-save-v1';
const morphs=['Mack Snow','Tangerine','Bell Albino','Tremper Albino','Eclipse','Enigma','RAPTOR','Super Snow','Bold Stripe','Carrot Tail','Lavender','Hypo'];
const genePool=['Snow','Tangerine','Albino','Eclipse','Stripe','Hypo','Lavender','Carrot Tail','Mack Snow','Bold Stripe'];
const seedGeckos=[
 {id:'g1',name:'Saffron',morph:'Tangerine Carrot Tail',sex:'Female',age:18,price:180,genes:['Tangerine','Carrot Tail'],color:'#eaa653',pattern:'#bd6438',health:94,origin:'Homebred',line:'Mesa Sunset'},
 {id:'g2',name:'Mochi',morph:'Mack Snow',sex:'Male',age:14,price:220,genes:['Mack Snow'],color:'#e8dfc9',pattern:'#716553',health:100,origin:'Purchased',line:'Cloud Nine'},
 {id:'g3',name:'Pixel',morph:'Bold Stripe',sex:'Female',age:21,price:145,genes:['Bold Stripe','Hypo'],color:'#e5b973',pattern:'#9c6845',health:88,origin:'Homebred',line:'Mesa Sunset'},
 {id:'g4',name:'Juniper',morph:'Bell Albino',sex:'Female',age:12,price:195,genes:['Albino'],color:'#f0c98e',pattern:'#be9867',health:97,origin:'Purchased',line:'Copperlight'},
 {id:'g5',name:'Clover',morph:'Eclipse',sex:'Male',age:16,price:260,genes:['Eclipse','Snow'],color:'#b8b2a1',pattern:'#665c52',health:91,origin:'Trade',line:'Moonstone'}
];
const initialState={money:2480,geckos:seedGeckos,feed:{mealworms:42,crickets:30},habitats:5,rackLevel:1,incubator:0,eggs:0,day:1,activity:[{icon:'✦',title:'Spring season started',detail:'Your first breeding season is here'},{icon:'♡',title:'Meet your new geckos',detail:'5 geckos are settling in'},{icon:'⌖',title:'Phoenix Reptile Expo',detail:'Next stop · Phoenix, Arizona'}],sold:0,ownedExpos:[],lastBreed:null};
let state=loadState();let activeView='home';let collectionFilter='All';
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&Array.isArray(saved.geckos))return {...initialState,...saved}}catch(e){}return structuredClone(initialState)}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateTop()}
function updateTop(){document.getElementById('money-display').textContent=state.money.toLocaleString();document.getElementById('gecko-count').textContent=state.geckos.length}
function money(n){return '$'+Math.round(n).toLocaleString()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setView(view){activeView=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={home:'Overview',collection:'My geckos',breeding:'Breeding lab',market:'Marketplace',supplies:'Food & habitat',expos:'Expo tour'};document.getElementById('crumb-title').textContent=titles[view]||'Overview';document.body.classList.remove('mobile-open');render()}
function toast(msg){const el=document.createElement('div');el.className='toast';el.innerHTML='<span>✦</span>'+msg;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3000)}
function addActivity(icon,title,detail){state.activity.unshift({icon,title,detail});state.activity=state.activity.slice(0,6)}
function geckoArt(g,cls='gecko-svg'){let c=g.color||'#e4b772',p=g.pattern||'#9f6945';return `<svg class="${cls}" viewBox="0 0 220 130" aria-hidden="true"><defs><linearGradient id="skin-${g.id}" x1="0" x2="1" y1="0" y2="1"><stop stop-color="${c}"/><stop offset="1" stop-color="${shade(c,-20)}"/></linearGradient></defs><path d="M52 77 C32 82 20 98 9 96 C22 88 23 78 39 70 C55 61 64 66 77 61" fill="none" stroke="url(#skin-${g.id})" stroke-width="12" stroke-linecap="round"/><ellipse cx="107" cy="72" rx="48" ry="27" fill="url(#skin-${g.id})"/><path d="M139 60 Q153 40 177 44 Q197 47 200 59 Q202 70 186 75 Q164 82 143 78Z" fill="url(#skin-${g.id})"/><ellipse cx="183" cy="54" rx="5.4" ry="7" fill="${g.morph.toLowerCase().includes('eclipse')?'#221f20':'#d69c43'}"/><ellipse cx="184" cy="54" rx="2" ry="5" fill="#22211f"/><circle cx="185" cy="51.5" r="1.3" fill="white"/><path d="M165 76 Q171 86 178 77 M181 76 Q187 86 192 76" stroke="${shade(c,-28)}" stroke-width="4" stroke-linecap="round"/><path d="M82 88 L73 105 M104 94 L99 108 M133 91 L139 103" stroke="${shade(c,-22)}" stroke-width="5" stroke-linecap="round"/><path d="M72 57 Q91 45 102 49 M112 48 Q130 50 140 59" stroke="${p}" stroke-width="7" stroke-linecap="round" opacity=".8"/><circle cx="87" cy="68" r="3" fill="${p}"/><circle cx="103" cy="83" r="3" fill="${p}"/><circle cx="124" cy="67" r="3.5" fill="${p}"/><circle cx="152" cy="54" r="2.3" fill="${p}"/><circle cx="161" cy="68" r="2" fill="${p}"/><path d="M35 73 Q47 70 55 74" stroke="${p}" stroke-width="3" opacity=".8"/></svg>`}
function shade(hex,amount){if(!/^#[\da-f]{6}$/i.test(hex))return hex;let v=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(v>>16)+amount)),g=Math.max(0,Math.min(255,((v>>8)&255)+amount)),b=Math.max(0,Math.min(255,(v&255)+amount));return '#'+(0x1000000+r*65536+g*256+b).toString(16).slice(1)}
function geckoCard(g){return `<article class="gecko-card" data-gecko="${g.id}"><div class="gecko-art"><span class="sex-pill">${g.sex==='Female'?'♀':'♂'} &nbsp;${g.sex}</span><span class="rarity-dot"></span>${geckoArt(g)}</div><div class="gecko-info"><div class="gecko-title-line"><h3>${esc(g.name)}</h3><span class="gecko-price">${money(g.price)}</span></div><div class="gecko-morph">${esc(g.morph)} · ${g.age} mo</div><div class="gecko-tags">${(g.genes||[]).slice(0,2).map((x,i)=>`<span class="tag ${i===0?'gold':''}">${esc(x)}</span>`).join('')}<span class="tag">${g.health}% health</span></div></div></article>`}
function heading(kicker,title,desc,button=''){return `<div class="page-heading"><div><div class="greeting">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function render(){const root=document.getElementById('view-root');const pages={home:renderHome,collection:renderCollection,breeding:renderBreeding,market:renderMarket,supplies:renderSupplies,expos:renderExpos};root.innerHTML=(pages[activeView]||renderHome)();bindPage();updateTop()}
function renderHome(){const best=state.geckos.slice().sort((a,b)=>b.price-a.price).slice(0,3);let next=['Phoenix Reptile Expo','Tucson Herp Fair','Desert Gecko Showcase'][state.day%3];return `${heading('WEDNESDAY, SPRING · DAY '+state.day,'Good morning, Jamie ✳','A fresh day in the studio. Your geckos are looking lovely.',`<button class="primary-button" data-action="open-breed"><span class="btn-icon">＋</span>Plan a pairing</button>`)}<div class="dashboard-grid"><div><section class="hero-card"><div class="hero-bg"></div><div class="hero-content"><div class="hero-kicker"><span></span> YOUR BREEDING SEASON</div><h2>Small scales.<br>Big possibilities.</h2><p>Pair your favorite geckos and discover the next one-of-a-kind morph.</p><button class="primary-button" data-action="open-breed">Explore the breeding lab <span class="btn-icon">→</span></button></div><svg class="hero-art" viewBox="0 0 220 150" aria-label="Illustration of a leopard gecko"><path d="M54 91 C31 92 20 110 9 108 C23 99 23 88 42 82 C57 76 65 80 78 73" fill="none" stroke="#d5a467" stroke-width="14" stroke-linecap="round"/><ellipse cx="112" cy="83" rx="52" ry="32" fill="#e6bd77"/><path d="M142 67 Q155 46 182 50 Q205 53 207 68 Q207 80 190 85 Q167 91 145 83Z" fill="#e8c27f"/><ellipse cx="190" cy="61" rx="6" ry="8" fill="#bb8d44"/><ellipse cx="191" cy="61" rx="2.3" ry="5.5" fill="#24221f"/><circle cx="192" cy="58" r="1.5" fill="#fff"/><path d="M89 57 Q102 50 111 53 M121 53 Q134 55 142 65 M88 85 Q96 78 102 83 M113 95 Q121 87 126 92" stroke="#ba7847" stroke-width="8" stroke-linecap="round"/><path d="M89 103 L80 124 M110 109 L105 128 M139 104 L146 120" stroke="#d2a766" stroke-width="6" stroke-linecap="round"/><circle cx="159" cy="59" r="3" fill="#aa7042"/><circle cx="172" cy="77" r="2.7" fill="#aa7042"/><circle cx="129" cy="77" r="3.2" fill="#aa7042"/><circle cx="102" cy="71" r="2.8" fill="#aa7042"/></svg></section><div class="hero-stats"><div class="stat"><div class="stat-label">IN YOUR COLLECTION</div><div class="stat-value">${state.geckos.length}<span class="stat-note">geckos</span></div></div><div class="stat"><div class="stat-label">HATCHLINGS RAISED</div><div class="stat-value">${state.sold+state.eggs}<span class="stat-note">this season</span></div></div><div class="stat"><div class="stat-label">YOUR STUDIO RATING</div><div class="stat-value">${Math.min(5,Math.round((state.geckos.reduce((a,g)=>a+g.health,0)/(state.geckos.length||1))/20))}.0<span class="stat-note">★</span></div></div></div><div class="section-row"><h2 class="section-title">Meet the crew</h2><button class="text-link" data-view="collection">View all geckos →</button></div><div class="gecko-grid">${best.map(geckoCard).join('')}</div><div class="mini-section"><div class="section-row"><h2 class="section-title">Around the studio</h2><span class="eyebrow">LATEST NOTES</span></div><div class="activity-list">${state.activity.slice(0,3).map(a=>`<div class="activity-item"><div class="activity-icon">${a.icon}</div><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div></div>`).join('')}</div></div></div><aside class="right-column"><section class="card"><div class="card-head"><h3>Today's care</h3><button class="text-link" data-action="care-all">Care all</button></div><div class="care-card"><div class="care-row"><div class="care-symbol">◉</div><div><strong>Fresh water</strong><small>Check every habitat</small></div><span class="care-tag">LOOKS GOOD</span></div><div class="care-row"><div class="care-symbol">♧</div><div><strong>Feeding time</strong><small>${state.feed.mealworms+state.feed.crickets} portions in stock</small></div><span class="care-tag">READY</span></div><div class="care-row"><div class="care-symbol">☼</div><div><strong>Habitat check</strong><small>${state.habitats} cozy homes</small></div><span class="care-tag">ALL SET</span></div></div></section><section class="expo-card"><div class="expo-date">UP NEXT · DAY ${state.day+3}</div><h3>${next}</h3><p>Meet fellow keepers & find your next star.</p><button class="soft-button" data-view="expos">Plan your expo trip →</button></section><section class="card"><div class="card-head"><h3>Studio snapshot</h3><span class="eyebrow">TODAY</span></div><div class="care-card"><div class="care-row"><div class="care-symbol">＄</div><div><strong>Available funds</strong><small>Ready for supplies & upgrades</small></div><b style="margin-left:auto;font-size:10px;color:#52745a">${money(state.money)}</b></div><div class="care-row"><div class="care-symbol">▧</div><div><strong>Habitat capacity</strong><small>${state.geckos.length} of ${state.habitats} spots in use</small></div><b style="margin-left:auto;font-size:10px;color:#52745a">${Math.max(0,state.habitats-state.geckos.length)} open</b></div></div></section></aside></div>`}

