function renderHome(){const best=state.geckos.slice().sort((a,b)=>b.price-a.price).slice(0,3);let next=['Phoenix Reptile Expo','Tucson Herp Fair','Desert Gecko Showcase'][state.day%3];return `${heading('WEDNESDAY, SPRING · DAY '+state.day,'Good morning, Jamie ✳','A fresh day in the studio. Your geckos are looking lovely.',`<button class="primary-button" data-action="open-breed"><span class="btn-icon">＋</span>Plan a pairing</button>`)}<div class="dashboard-grid"><div><section class="hero-card"><div class="hero-bg"></div><div class="hero-content"><div class="hero-kicker"><span></span> YOUR BREEDING SEASON</div><h2>Small scales.<br>Big possibilities.</h2><p>Pair your favorite geckos and discover the next one-of-a-kind morph.</p><button class="primary-button" data-action="open-breed">Explore the breeding lab <span class="btn-icon">→</span></button></div><svg class="hero-art" viewBox="0 0 220 150" aria-label="Illustration of a leopard gecko"><path d="M54 91 C31 92 20 110 9 108 C23 99 23 88 42 82 C57 76 65 80 78 73" fill="none" stroke="#d5a467" stroke-width="14" stroke-linecap="round"/><ellipse cx="112" cy="83" rx="52" ry="32" fill="#e6bd77"/><path d="M142 67 Q155 46 182 50 Q205 53 207 68 Q207 80 190 85 Q167 91 145 83Z" fill="#e8c27f"/><ellipse cx="190" cy="61" rx="6" ry="8" fill="#bb8d44"/><ellipse cx="191" cy="61" rx="2.3" ry="5.5" fill="#24221f"/><circle cx="192" cy="58" r="1.5" fill="#fff"/><path d="M89 57 Q102 50 111 53 M121 53 Q134 55 142 65 M88 85 Q96 78 102 83 M113 95 Q121 87 126 92" stroke="#ba7847" stroke-width="8" stroke-linecap="round"/><path d="M89 103 L80 124 M110 109 L105 128 M139 104 L146 120" stroke="#d2a766" stroke-width="6" stroke-linecap="round"/><circle cx="159" cy="59" r="3" fill="#aa7042"/><circle cx="172" cy="77" r="2.7" fill="#aa7042"/><circle cx="129" cy="77" r="3.2" fill="#aa7042"/><circle cx="102" cy="71" r="2.8" fill="#aa7042"/></svg></section><div class="hero-stats"><div class="stat"><div class="stat-label">IN YOUR COLLECTION</div><div class="stat-value">${state.geckos.length}<span class="stat-note">geckos</span></div></div><div class="stat"><div class="stat-label">HATCHLINGS RAISED</div><div class="stat-value">${state.sold+state.eggs}<span class="stat-note">this season</span></div></div><div class="stat"><div class="stat-label">YOUR STUDIO RATING</div><div class="stat-value">${Math.min(5,Math.round((state.geckos.reduce((a,g)=>a+g.health,0)/(state.geckos.length||1))/20))}.0<span class="stat-note">★</span></div></div></div><div class="section-row"><h2 class="section-title">Meet the crew</h2><button class="text-link" data-view="collection">View all geckos →</button></div><div class="gecko-grid">${best.map(geckoCard).join('')}</div><div class="mini-section"><div class="section-row"><h2 class="section-title">Around the studio</h2><span class="eyebrow">LATEST NOTES</span></div><div class="activity-list">${state.activity.slice(0,3).map(a=>`<div class="activity-item"><div class="activity-icon">${a.icon}</div><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div></div>`).join('')}</div></div></div><aside class="right-column"><section class="card"><div class="card-head"><h3>Today's care</h3><button class="text-link" data-action="care-all">Care all</button></div><div class="care-card"><div class="care-row"><div class="care-symbol">◉</div><div><strong>Fresh water</strong><small>Check every habitat</small></div><span class="care-tag">LOOKS GOOD</span></div><div class="care-row"><div class="care-symbol">♧</div><div><strong>Feeding time</strong><small>${state.feed.mealworms+state.feed.crickets} portions in stock</small></div><span class="care-tag">READY</span></div><div class="care-row"><div class="care-symbol">☼</div><div><strong>Habitat check</strong><small>${state.habitats} cozy homes</small></div><span class="care-tag">ALL SET</span></div></div></section><section class="expo-card"><div class="expo-date">UP NEXT · DAY ${state.day+3}</div><h3>${next}</h3><p>Meet fellow keepers & find your next star.</p><button class="soft-button" data-view="expos">Plan your expo trip →</button></section><section class="card"><div class="card-head"><h3>Studio snapshot</h3><span class="eyebrow">TODAY</span></div><div class="care-card"><div class="care-row"><div class="care-symbol">＄</div><div><strong>Available funds</strong><small>Ready for supplies & upgrades</small></div><b style="margin-left:auto;font-size:10px;color:#52745a">${money(state.money)}</b></div><div class="care-row"><div class="care-symbol">▧</div><div><strong>Habitat capacity</strong><small>${state.geckos.length} of ${state.habitats} spots in use</small></div><b style="margin-left:auto;font-size:10px;color:#52745a">${Math.max(0,state.habitats-state.geckos.length)} open</b></div></div></section></aside></div>`}
function renderCollection(){const filtered=state.geckos.filter(g=>collectionFilter==='All'||g.sex===collectionFilter||g.genes.includes(collectionFilter));return `${heading('YOUR STUDIO','My geckos','Every gecko has a story. Keep an eye on their health, genes, and habitat.',`<button class="primary-button" data-view="market"><span class="btn-icon">＋</span>Find a gecko</button>`)}<div class="content-card"><div class="toolbar">${['All','Female','Male','Snow','Albino','Tangerine'].map(f=>`<button class="filter-chip ${collectionFilter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}<input class="search-input" id="gecko-search" placeholder="⌕  Search your geckos" /></div><div class="gecko-grid full-grid" id="collection-grid">${filtered.map(geckoCard).join('')||'<div class="empty-state">No geckos match this filter.</div>'}</div></div><div class="section-row"><h2 class="section-title">A little husbandry note</h2><span class="eyebrow">KEEP THEM THRIVING</span></div><div class="activity-list"><div class="activity-item"><div class="activity-icon">☀</div><div><strong>Warm side 88–92°F</strong><small>Give them a gradient to choose from</small></div></div><div class="activity-item"><div class="activity-icon">♧</div><div><strong>Gut-load your feeders</strong><small>Happy feeders make healthy geckos</small></div></div><div class="activity-item"><div class="activity-icon">◉</div><div><strong>Fresh water, every day</strong><small>Simple routines go a long way</small></div></div></div>`}
function renderBreeding(){let females=state.geckos.filter(g=>g.sex==='Female'),males=state.geckos.filter(g=>g.sex==='Male');if(!females.length||!males.length)return `${heading('THE BREEDING ROOM','Breeding lab','Pair compatible adults and see what your line might become.') }<div class="empty-state"><div style="font-size:35px">♡</div><h3>You need a male and female</h3><p>Visit the marketplace to find a breeding partner.</p><button class="primary-button" data-view="market">Browse geckos</button></div>`;let f=females[0],m=males[0];return `${heading('THE BREEDING ROOM','Breeding lab','Pair compatible adults and see what your line might become.',`<span class="tag gold">${state.eggs} eggs in incubator</span>`)}<div class="lab-grid"><section class="content-card"><h2 class="panel-title">Plan a pairing</h2><p class="panel-sub">A little genetics, a little luck, and a lot of care.</p><label class="select-label" for="mother-select">FEMALE · DAM</label><select class="select-control" id="mother-select">${females.map(g=>`<option value="${g.id}">${esc(g.name)} — ${esc(g.morph)}</option>`).join('')}</select><label class="select-label" for="father-select">MALE · SIRE</label><select class="select-control" id="father-select">${males.map(g=>`<option value="${g.id}">${esc(g.name)} — ${esc(g.morph)}</option>`).join('')}</select><div class="parent-preview" id="parent-preview"></div><div class="prediction"><div class="prediction-mark">✦</div><div><strong id="prediction-title">A little of each, a lot of possibility</strong><small id="prediction-copy">Possible traits are shown as an educated guess — real genetics can surprise you.</small></div></div><button class="primary-button" style="width:100%" id="breed-button">♡ &nbsp; Pair these geckos · $45 care cost</button><div id="breed-feedback"></div></section><section class="content-card"><h2 class="panel-title">Your gene notebook</h2><p class="panel-sub">Known morphs in your line, plus recessive traits to watch.</p><div class="genetics-list">${[...new Set(state.geckos.flatMap(g=>g.genes))].map((gene,i)=>`<div class="genetics-row"><div class="gene-badge">${['✧','◈','✦','❋'][i%4]}</div><div><strong>${esc(gene)}</strong><small>${morphDesc(gene)}</small></div><span class="gene-value">${state.geckos.filter(g=>g.genes.includes(gene)).length} carrier${state.geckos.filter(g=>g.genes.includes(gene)).length!==1?'s':''}</span></div>`).join('')}<div class="genetics-row"><div class="gene-badge">＋</div><div><strong>Unknown combinations</strong><small>Your future line starts with a pairing.</small></div><span class="gene-value">DISCOVER</span></div></div><div class="breed-result"><strong>Breeder's note</strong><br>Named morphs like Mack Snow and Eclipse describe traits; a new line is built over generations by selecting offspring with the qualities you want. Take good records and breed responsibly.</div></section></div>`}
function morphDesc(g){return ({Snow:'Light body with reduced yellow pigmentation.',Tangerine:'Warm orange color selected over generations.',Albino:'A recessive family; never combine albino strains.',Eclipse:'Solid eyes, often paired with other traits.',Stripe:'Longitudinal pattern instead of bands.',Hypo:'Reduced body spotting.',Lavender:'Soft purple undertones in selected lines.','Carrot Tail':'Orange pigment concentrated at the tail.','Mack Snow':'Co-dominant snow pattern; super form is brighter.','Bold Stripe':'High-contrast dorsal stripe selection.'})[g]||'A trait in your growing collection.'}
function renderMarket(){let offers=[{name:'Tango',morph:'Tangerine het Tremper',sex:'Male',price:175,genes:['Tangerine','Albino'],color:'#eaa15a',pattern:'#bd6739',health:98,age:10,from:'Sandy S.',line:'Copperlight'},{name:'Opal',morph:'Super Snow Eclipse',sex:'Female',price:420,genes:['Snow','Eclipse'],color:'#d9d4c2',pattern:'#6a6255',health:96,age:15,from:'Crested Moon Geckos',line:'Nightfall'},{name:'Sol',morph:'Bell Albino',sex:'Male',price:235,genes:['Albino','Bold Stripe'],color:'#f0c787',pattern:'#c6955e',health:99,age:13,from:'Ridgeview Reptiles',line:'Sunstripe'},{name:'Fig',morph:'Lavender Stripe',sex:'Female',price:310,genes:['Lavender','Stripe'],color:'#c0aaa1',pattern:'#826b68',health:95,age:12,from:'Mossy Rock Geckos',line:'Heather'},{name:'Mango',morph:'Hypo Tangerine',sex:'Male',price:155,genes:['Hypo','Tangerine'],color:'#eab46b',pattern:'#c57e43',health:93,age:9,from:'Desert Bloom',line:'Goldrush'},{name:'Dottie',morph:'Mack Snow',sex:'Female',price:205,genes:['Mack Snow','Carrot Tail'],color:'#e3dbc6',pattern:'#756755',health:97,age:11,from:'Gecko Garden',line:'Cloud Nine'}];return `${heading('THE COMMUNITY','Marketplace','Meet geckos from fellow keepers, or share one of your own.',`<button class="secondary-button" data-action="list-gecko">⇧ &nbsp;List a gecko</button>`)}<div class="toolbar">${['Featured','Morphs','Lines','Recent'].map((x,i)=>`<button class="filter-chip ${i===0?'active':''}" data-market-filter>${x}</button>`).join('')}<span class="stock-label" style="margin-left:auto">Friendly keeper listings · No real-money trades</span></div><div class="market-grid">${offers.map((g,i)=>`<article class="listing-card"><div class="listing-art">${geckoArt({...g,id:'offer'+i})}</div><div class="listing-body"><div class="listing-top"><h3>${g.name}</h3><span class="listing-price">${money(g.price)}</span></div><p>${g.morph} · ${g.sex} · ${g.age} mo</p><div class="listing-footer"><span class="stock-label">♡ ${g.from}</span><button class="soft-button" data-action="buy-gecko" data-offer="${i}">Meet ${g.name}</button></div></div></article>`).join('')}</div><div class="section-row"><h2 class="section-title">Trade board</h2><span class="eyebrow">KEEPER-TO-KEEPER</span></div><div class="content-card"><div class="trade-offer"><div><strong>Looking for a high-expression Snow female</strong><small>Riley's Reptile Room · offers a Tangerine het Eclipse male</small></div><button class="soft-button" data-action="trade">Propose trade</button></div><div class="trade-offer"><div><strong>Seeking a new home for a Bold Stripe male</strong><small>Desert Bloom Geckos · open to fair offers</small></div><button class="soft-button" data-action="trade">Propose trade</button></div></div>`}

