function modal(content){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal">${content}</div></div>`;root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b))}
function updatePairing(){let f=state.geckos.find(g=>g.id===document.getElementById('mother-select').value),m=state.geckos.find(g=>g.id===document.getElementById('father-select').value);if(!f||!m)return;document.getElementById('parent-preview').innerHTML=`<div class="parent-tile"><div class="parent-thumb">${geckoArt(f)}</div><div><strong>${esc(f.name)}</strong><small>${esc(f.morph)}</small></div></div><div class="heart-plus">♡</div><div class="parent-tile"><div class="parent-thumb">${geckoArt(m)}</div><div><strong>${esc(m.name)}</strong><small>${esc(m.morph)}</small></div></div>`;let genes=[...new Set([...f.genes,...m.genes])];document.getElementById('prediction-title').textContent=genes.length>1?genes.slice(0,2).join(' × ')+' possibilities':'A little of each, a lot of possibility';document.getElementById('prediction-copy').textContent=`Possible traits: ${genes.join(', ')}. Pairing is a playful estimate, not guaranteed genetics.`}
