function handleAction(button){let a=button.dataset.action;if(a==='open-breed'){setView('breeding');return}if(a==='care-all'){state.day++;state.geckos.forEach(g=>g.health=Math.min(100,g.health+5));addActivity('☘','Daily care complete','Fresh water and a check-in for every gecko');save();render();toast('Care done — everyone is feeling a little better!');return}if(a==='buy-gecko'){let g=window.marketOffers[Number(button.dataset.offer)];if(state.money<g.price){toast('Not enough funds for '+g.name+'.');return}if(state.habitats-state.geckos.length<1){toast('No free habitat spots — upgrade first.');return}state.money-=g.price;state.geckos.push({...g,id:'p'+Date.now(),origin:'Purchased'});addActivity('◉',g.name+' joined your crew',g.morph+' · from '+g.from);save();render();toast('Welcome, '+g.name+'! They are settling in.');return}if(a==='buy-supply'){buySupply(button.dataset.product);return}if(a==='visit-expo'){visitExpo(button);return}if(a==='list-gecko'||a==='sell-one'){openSell(button.dataset.id);return}if(a==='trade'){modal(`<div class="modal-head"><div><h2>Propose a keeper trade</h2><p>Choose a gecko from your collection to offer.</p></div><button class="close-modal" data-close>×</button></div><label class="select-label">YOUR OFFER</label><select class="select-control" id="trade-gecko">${state.geckos.map(g=>`<option value="${g.id}">${esc(g.name)} — ${esc(g.morph)}</option>`).join('')}</select><div class="breed-result">This is a fictional keeper-to-keeper trade board. The other breeder will consider your offer.</div><div class="modal-actions"><button class="soft-button" data-close>Cancel</button><button class="primary-button" id="send-trade">Send offer</button></div>`);document.getElementById('send-trade').onclick=()=>{let id=document.getElementById('trade-gecko').value,g=state.geckos.find(x=>x.id===id);modal(`<div class="modal-head"><div><h2>Offer sent ✦</h2><p>Your note is on its way to the other keeper.</p></div><button class="close-modal" data-close>×</button></div><p style="font-size:11px;color:#77857a;line-height:1.6">You offered ${esc(g.name)} (${esc(g.morph)}). In this solo game, trades are flavor interactions and do not remove your gecko.</p><div class="modal-actions"><button class="primary-button" data-close>Sounds good</button></div>`)};return}if(a==='open-expo'){modal(`<div class="modal-head"><div><h2>Expo day, the fun way</h2><p>Choose a state, pay the travel fee, and meet the crowd.</p></div><button class="close-modal" data-close>×</button></div><div class="breed-result"><strong>How it works</strong><br>Travel costs vary by distance. Each expo has different buyers. You can sell up to two geckos each trip; prices depend on each gecko's estimated value and the local crowd. All transactions use in-game coins.</div><div class="modal-actions"><button class="primary-button" data-close>Let's go</button></div>`);return}}
function buySupply(id){let prices={mealworms:18,crickets:22,calcium:16,water:28,rack:240,enclosure:180,incubator:320},price=prices[id];if(state.money<price){toast('Not enough coins for that supply.');return}if(id==='rack'||id==='enclosure'){state.habitats+=id==='rack'?2:1;if(id==='rack')state.rackLevel++}else if(id==='incubator'){state.incubator++;}else if(id==='mealworms')state.feed.mealworms+=25;else if(id==='crickets')state.feed.crickets+=25;else if(id==='calcium'){state.geckos.forEach(g=>g.health=Math.min(100,g.health+4))}else if(id==='water'){state.geckos.forEach(g=>g.health=Math.min(100,g.health+2))}state.money-=price;addActivity('▤','Supply delivery arrived',id==='rack'||id==='enclosure'?'Your habitat capacity increased.':id==='incubator'?'A careful home for future eggs.':id+' added to your care kit');save();render();toast('Purchase complete — thanks for caring!')}
function visitExpo(button){let name=button.dataset.expo,fee=Number(button.dataset.fee),bonus=Number(button.dataset.bonus);if(state.money<fee){toast('You need '+money(fee)+' for travel.');return}state.money-=fee;let buyers=Math.min(2,state.geckos.length),sold=[];for(let i=0;i<buyers;i++){let g=state.geckos.slice().sort((a,b)=>a.price-b.price)[Math.floor(Math.random()*Math.min(3,state.geckos.length))];if(!g)break;let value=Math.round(g.price*bonus*(0.78+Math.random()*.42));sold.push({g,value});state.geckos=state.geckos.filter(x=>x.id!==g.id);state.money+=value;state.sold++}state.ownedExpos.push(name);state.day++;addActivity('⌖','A day at '+name,`${sold.length} gecko${sold.length===1?'':'s'} found a new home`);save();render();modal(`<div class="modal-head"><div><h2>What a lovely expo day!</h2><p>${esc(name)} · the booth is packed away.</p></div><button class="close-modal" data-close>×</button></div><div class="breed-result">${sold.map(x=>`<strong>${esc(x.g.name)}</strong> (${esc(x.g.morph)}) found a new home for ${money(x.value)}.<br>`).join('')||'Your booth had no visitors this time.'}<br><strong>Travel:</strong> −${money(fee)} · <strong>Net:</strong> ${money(sold.reduce((a,x)=>a+x.value,0)-fee)}</div><div class="modal-actions"><button class="primary-button" data-close>Home sweet home</button></div>`)}
function openSell(id){if(!state.geckos.length){toast('You have no geckos to list.');return}let options=state.geckos.map(g=>`<option value="${g.id}" ${id===g.id?'selected':''}>${esc(g.name)} — ${esc(g.morph)} (${money(g.price)})</option>`).join('');modal(`<div class="modal-head"><div><h2>List a gecko</h2><p>Give a special gecko a new home in the community.</p></div><button class="close-modal" data-close>×</button></div><label class="select-label">CHOOSE A GECKO</label><select class="select-control" id="sell-gecko">${options}</select><label class="select-label">ASKING PRICE</label><input class="select-control" type="number" id="sell-price" min="1" value="${id?state.geckos.find(g=>g.id===id)?.price||100:100}" /><div class="breed-result">Listing is a friendly solo-game sale: the gecko leaves your collection and you receive the asking price.</div><div class="modal-actions"><button class="soft-button" data-close>Cancel</button><button class="primary-button" id="confirm-sell">List gecko</button></div>`);document.getElementById('confirm-sell').onclick=()=>{let g=state.geckos.find(x=>x.id===document.getElementById('sell-gecko').value),price=Math.max(1,Number(document.getElementById('sell-price').value)||g.price);state.geckos=state.geckos.filter(x=>x.id!==g.id);state.money+=price;state.sold++;addActivity('⇄',g.name+' found a new home','Community sale · '+money(price));save();document.getElementById('modal-root').innerHTML='';render();toast(g.name+' sold for '+money(price)+'!')}}

