+document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById('mobile-menu').onclick=()=>document.body.classList.toggle('mobile-open');document.getElementById('help-button').onclick=()=>modal(`<div class="modal-head"><div><h2>Welcome to Terrarium</h2><p>Your cozy leopard gecko breeding studio.</p></div><button class="close-modal" data-close>×</button></div><div class="breed-result"><strong>Your goals</strong><br>• Care for your geckos and keep their habitats roomy.<br>• Pair adult geckos to discover combinations and build new lines.<br>• Stock feeders and buy habitat upgrades in the shop.<br>• Meet keepers, trade, sell, and visit expos around the states.<br><br><strong>Game note:</strong> Morph names reference real leopard gecko morphs and lines, but all genetics and transactions here are simplified for play. Real breeding requires proper welfare, research, and responsible pairing.</div><div class="modal-actions"><button class="primary-button" data-close>Got it</button></div>`);updateTop();render();

